def merge(intervals):
    if not intervals:
        return []
    # Sort intervals by start
    intervals.sort()
    merged = [intervals[0]]
    for current in intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping or touching, merge them
            merged[-1] = (last[0], max(last[1], current[1]))
        else:
            merged.append(current)
    return merged


def free_gaps(intervals, window):
    ws, we = window
    # Sort intervals by start
    intervals.sort()
    gaps = []
    # Add the initial gap from ws to the first interval's start
    if intervals:
        first_start = intervals[0][0]
        if first_start > ws:
            gaps.append((ws, first_start))
    else:
        gaps.append((ws, we))
    # Process intervals to find gaps
    for i in range(len(intervals) - 1):
        current_end = intervals[i][1]
        next_start = intervals[i + 1][0]
        if current_end < next_start:
            gaps.append((current_end, next_start))
    # Add the gap after the last interval
    if intervals:
        last_end = intervals[-1][1]
        if last_end < we:
            gaps.append((last_end, we))
    return gaps


def max_overlap(intervals):
    if not intervals:
        return 0
    # Sort intervals by start
    intervals.sort()
    # Initialize max overlap and current overlap
    max_overlap = 1
    current_overlap = 1
    # Iterate through intervals
    for i in range(1, len(intervals)):
        # If the current interval starts before or at the end of the previous one, it overlaps
        if intervals[i][0] <= intervals[i - 1][1]:
            current_overlap += 1
            max_overlap = max(max_overlap, current_overlap)
        else:
            current_overlap = 1
    return max_overlap

import time

class TTLCache:
    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        self.capacity = capacity
        self.clock = clock
        self.cache = {}
        self.keys = []

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("TTL must be positive")
        # Remove expired entries
        self._evict_expired()
        # Check if the cache is full
        if len(self.cache) >= self.capacity:
            # Evict the least recently used entry
            if self.keys:
                lru_key = self.keys[0]
                del self.cache[lru_key]
                self.keys.pop(0)
        # Add the new entry
        current_time = self.clock()
        if ttl is None:
            expiration_time = float('inf')
        else:
            expiration_time = current_time + ttl
        self.cache[key] = (value, expiration_time)
        # Update the most recently used entry
        if key in self.keys:
            self.keys.remove(key)
        self.keys.append(key)

    def get(self, key, default=None):
        current_time = self.clock()
        # Check if the key is present and not expired
        if key in self.cache:
            value, expiration_time = self.cache[key]
            if current_time < expiration_time:
                # Make the entry the most recently used
                self.keys.remove(key)
                self.keys.append(key)
                return value
            else:
                # Remove the expired entry
                del self.cache[key]
                self.keys.remove(key)
        return default

    def __contains__(self, key):
        current_time = self.clock()
        return key in self.cache and current_time < self.cache[key][1]

    def __len__(self):
        current_time = self.clock()
        return sum(1 for value, expiration_time in self.cache.values() if current_time < expiration_time)

    def keys(self):
        current_time = self.clock()
        # Filter out expired entries
        live_keys = [key for key in self.keys if current_time < self.cache[key][1]]
        return live_keys

    def evict_expired(self):
        current_time = self.clock()
        removed = 0
        # Filter out expired entries
        new_cache = {}
        new_keys = []
        for key in self.keys:
            value, expiration_time = self.cache[key]
            if current_time < expiration_time:
                new_cache[key] = (value, expiration_time)
                new_keys.append(key)
        # Update the cache and keys
        self.cache = new_cache
        self.keys = new_keys
        return len(self.cache) - len(new_cache)

